    public static function createGesamtplan(int $jahr1, int $dauerJahre): string
    {
        Page::Db()->beginTransaction();

        $erlaubteJahre = self::getJahrNeuerGesamtplan();
        if (!in_array($jahr1, $erlaubteJahre)) {
            return "Der IT-Gesamtplan für das Jahr $jahr1 konnte nicht angelegt werden.<br>Das Jahr 1 muss lückenlos "
                . "dem Zeitraum des letzten Gesamtplans folgen.";
        }

        $jahr2 = $dauerJahre === 2 ? $jahr1 + 1 : 'NULL';

        $letzterGesamtplan = self::getLetzterGesamtPlan();

        // 1. Datensatz für IT-Gesamtplan anlegen
        $sql = "INSERT INTO gesamtplan (jahr, jahr2, archived) VALUES ($jahr1, $jahr2, 0)";
        $statement = Page::db()->prepare($sql);
        if ($statement->execute()) {
            // 2. Formularfeld-Konfigurationen (dynform_field Datensätze kopieren, neue Version = $jahr1)
            $resultMessage = self::copyFormFields($jahr1, $letzterGesamtplan->jahr);

            if ($resultMessage === "OK") {
                $resultMessage = self::copyZweckListe($jahr1, $letzterGesamtplan->jahr);
                if ($resultMessage === "OK") {
                    Page::db()->commit();
                } else {
                    Page::Db()->rollBack();
                }
            } else {
                Page::Db()->rollBack();
            }
            return $resultMessage;
        } else {
            Page::db()->rollBack();
            //$errInfo = $statement->errorInfo();
            //return "DB-Fehler: " . $errInfo[0] . " | " . $errInfo[1] . "\nFehlermeldung: " . $errInfo[2] . "\nSQL-Anweisung: " . $statement->queryString . "\n\n";
            return "Der IT-Gesamtplan für das Jahr $jahr1 konnte nicht angelegt werden. Es ist ein Datenbankfehler aufgetreten.";
        }
    }

    /**
     * Kopiert allen Formularfeld-Definitions-Datensätze des vorherigen Gesamtplans für den neuen Gesamtplan
     * in der Datenbanktabelle dynform_field.
     * @param int $jahr1NeuerGesamtplan Jahr des neuen Gesamtplans
     * @param int $jahr1VorherigerGesamtplan Jahr des vorherigen Gesamtplans
     * @return string "OK" oder eine passendende Fehlermeldung.
     */
    protected static function copyFormFields(int $jahr1NeuerGesamtplan, int $jahr1VorherigerGesamtplan): string
    {
        $sql = "INSERT INTO dynform_field (
        db_table, version, name, label, type, type_options, description, class, readonly,
        required, aria_required, required_condition, disabled, multiline, max_lenght, min_lenght, auto_complete,
        configurable, active, sort
        )
        SELECT db_table, $jahr1NeuerGesamtplan, name, label, type, type_options, description, class, readonly,
        required, aria_required, required_condition, disabled, multiline, max_lenght, min_lenght, auto_complete,
        configurable, active, sort
        FROM dynform_field WHERE version = $jahr1VorherigerGesamtplan
        ";
        $statement = Page::db()->prepare($sql);
        if ($statement->execute()) {
            return "OK";
        } else {
            //$errInfo = $statement->errorInfo();
            //return "DB-Fehler: " . $errInfo[0] . " | " . $errInfo[1] . "\nFehlermeldung: " . $errInfo[2] . "\nSQL-Anweisung: " . $statement->queryString . "\n\n";
            return "Der IT-Gesamtplan für das Jahr $jahr1NeuerGesamtplan konnte nicht angelegt werden. Es ist ein Datenbankfehler aufgetreten. (2)";
        }
    }

    /**
     * @param int $jahr1NeuerGesamtplan Jahr des neuen Gesamtplans
     * @param int $jahr1VorherigerGesamtplan Jahr des vorherigen Gesamtplans
     * @return string "OK" oder eine passendende Fehlermeldung.
     */
    protected static function copyZweckListe(int $jahr1NeuerGesamtplan, int $jahr1VorherigerGesamtplan): string
    {
        $sql = "INSERT INTO zweck (version, nummer, bezeichnung)
                SELECT $jahr1NeuerGesamtplan, nummer, bezeichnung FROM zweck WHERE version = $jahr1VorherigerGesamtplan";
        $statement = Page::db()->prepare($sql);
        if ($statement->execute()) {
            return "OK";
        } else {
            //$errInfo = $statement->errorInfo();
            //return "DB-Fehler: " . $errInfo[0] . " | " . $errInfo[1] . "\nFehlermeldung: " . $errInfo[2] . "\nSQL-Anweisung: " . $statement->queryString . "\n\n";
            return "Der IT-Gesamtplan für das Jahr $jahr1NeuerGesamtplan konnte nicht angelegt werden. Es ist ein Datenbankfehler aufgetreten. (3)";
        }
    }

